using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using Client.Analysis;
using Client.Pages;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Web;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Xunit;

namespace Workspace.Tests.ThesisSource;

// The required fixture is generated by the actual built WASM runner. Controlled
// managed interop below establishes admission/capture behavior, not browser use.
public sealed class CitationNotesTests
{
    private static JsonObject Vectors => ThesisFixture.Resource("citation-notes-wasm-vectors");
    private static ThesisFixture Load(string id) => new(Vectors["vectors"]!.AsArray()
        .Single(v => v!["id"]!.GetValue<string>() == id)!.DeepClone().AsObject());
    public static IEnumerable<object[]> Cases => Vectors["vectors"]!.AsArray()
        .Select(v => new object[] { v!["id"]!.GetValue<string>() }).ToArray();

    [Fact]
    public void New_profile_is_explicit_and_preserves_historical_selection_and_catalog()
    {
        var old = AnalysisSelection.KnuWithThesis(AnalysisWorkType.Unspecified, "root");
        var current = AnalysisSelection.KnuWithCitationNotes(AnalysisWorkType.Unspecified, "root");
        Assert.Equal("1.5.0", old.Profile.Version);
        Assert.Equal("1.6.0", current.Profile.Version);
        Assert.True(old.IsValid && current.IsValid);
        Assert.True(AnalysisCatalog.IsThesis(old.Profile) && AnalysisCatalog.IsThesis(current.Profile));
        Assert.True(AnalysisCatalog.RequiresRoot(current.Profile));
        Assert.False((current with { ReferenceConfiguration = null }).IsValid);
        Assert.False((current with { Configuration = null }).IsValid);
        Assert.Equal("1.0.0", ThesisCatalog.Version);
        Assert.Equal("1.0.0", ThesisCatalog.VersionForProfile(old.Profile.Version));
        Assert.Equal("1.1.0", ThesisCatalog.VersionForProfile(current.Profile.Version));
        var legacy = ThesisCatalog.Rows.Single(r => r.GetProperty("ruleId").GetString() == "KNU-SRC-CITATIONS-001");
        var latest = ThesisCatalog.RowsForCatalog("1.1.0").Single(r => r.GetProperty("ruleId").GetString() == "KNU-SRC-CITATIONS-001");
        Assert.DoesNotContain("Profile 1.6", legacy.GetProperty("supportedSyntax").GetString());
        Assert.Contains("cite[postnote]", latest.GetProperty("supportedSyntax").GetString());
        Assert.Equal(legacy.GetProperty("citation").GetRawText(), latest.GetProperty("citation").GetRawText());
    }

    [Theory, MemberData(nameof(Cases))]
    public async Task Every_actual_WASM_vector_roundtrips_adapter_and_exact_capture(string id)
    {
        var data = Vectors;
        Assert.Equal("actual-node-wasm-not-browser", data["evidenceKind"]!.GetValue<string>());
        foreach (var name in new[] { "loaderSha256", "wasmSha256", "inputSha256" })
            Assert.Matches("^[0-9a-f]{64}$", data["producer"]![name]!.GetValue<string>());
        var fixture = Load(id);
        var original = Assert.IsType<AnalysisResponse.Completed>(AnalysisJson.ParseResponse(fixture.Response.ToJsonString()));
        var encoded = JsonSerializer.SerializeToElement(new AnalysisResponseEnvelope(1, original.RequestId,
            ResponseStatus.Completed, original.Result, null), AnalysisJson.Options);
        Assert.True(JsonElement.DeepEquals(JsonSerializer.SerializeToElement(fixture.Response), encoded));
        var snapshot = fixture.Snapshot();
        var bound = Assert.IsType<AnalysisResponse.Completed>(AnalysisJson.ParseResponse(fixture.Reply(snapshot, "notes")));
        ThesisValidation.ValidateCapturedResult(bound.Result, snapshot);
        var (metadata, bytes) = AnalysisRequestPacker.Pack(snapshot, "notes");
        Assert.Equal(fixture.Packed, bytes);
        Assert.Contains("\"version\":\"" + snapshot.Profile.Version + "\"", metadata);
        var js = new KnuProtocolTests.FixtureJs((_, requestId) => fixture.Reply(snapshot, requestId));
        await using var analyzer = new RustSourceAnalyzer(js);
        var result = Assert.IsType<AnalysisJobResult.Completed>(await analyzer.AnalyzeAsync(snapshot, default));
        Assert.Equal(snapshot.Profile.Version, result.Result.Profile.Version);
        Assert.Equal(snapshot.ReferenceConfiguration, result.Result.ReferenceConfiguration);
        Assert.Equal("notAssessed", result.Result.Thesis!.RenderedCompliance);
        Assert.Empty(result.Result.Knu!.FixDescriptors);
        Assert.Single(js.Calls);
    }

    [Theory]
    [InlineData("literal-no-note", RuleOutcome.Pass, RuleOutcome.Pass)]
    [InlineData("literal-postnote", RuleOutcome.Pass, RuleOutcome.Pass)]
    [InlineData("two-notes-uncertain", RuleOutcome.Indeterminate, RuleOutcome.Indeterminate)]
    [InlineData("empty-prenote-uncertain", RuleOutcome.Indeterminate, RuleOutcome.Indeterminate)]
    [InlineData("empty-both-uncertain", RuleOutcome.Indeterminate, RuleOutcome.Indeterminate)]
    [InlineData("literal-whitespace-comments", RuleOutcome.Pass, RuleOutcome.Pass)]
    [InlineData("literal-unicode-bom-crlf", RuleOutcome.Pass, RuleOutcome.Pass)]
    [InlineData("missing-key", RuleOutcome.Fail, RuleOutcome.Fail)]
    [InlineData("duplicate-key", RuleOutcome.Fail, RuleOutcome.Fail)]
    [InlineData("first-use-negative", RuleOutcome.Pass, RuleOutcome.Fail)]
    [InlineData("external-note", RuleOutcome.Pass, RuleOutcome.Unavailable)]
    [InlineData("dynamic-note", RuleOutcome.Indeterminate, RuleOutcome.Indeterminate)]
    [InlineData("malformed-note", RuleOutcome.Indeterminate, RuleOutcome.Indeterminate)]
    [InlineData("third-note", RuleOutcome.Indeterminate, RuleOutcome.Indeterminate)]
    [InlineData("starred-cite", RuleOutcome.Indeterminate, RuleOutcome.Indeterminate)]
    [InlineData("overlong-note", RuleOutcome.Indeterminate, RuleOutcome.Indeterminate)]
    [InlineData("dynamic-key", RuleOutcome.Indeterminate, RuleOutcome.Indeterminate)]
    [InlineData("legacy-note-uncertain", RuleOutcome.Indeterminate, RuleOutcome.Indeterminate)]
    public void Actual_producer_outcomes_preserve_resolution_order_and_uncertainty(string id, RuleOutcome citation, RuleOutcome bibliography)
    {
        var result = Assert.IsType<AnalysisResponse.Completed>(AnalysisJson.ParseResponse(Load(id).Response.ToJsonString())).Result;
        Assert.Equal(citation, result.Thesis!.RuleResults[1].Outcome);
        Assert.Equal(bibliography, result.Thesis.RuleResults[2].Outcome);
        Assert.Equal(5, result.Thesis.RuleResults.Length);
        Assert.Equal(7, result.RuleResults.Count);
    }

    [Theory]
    [InlineData("literal-postnote", "1.0.0")]
    [InlineData("legacy-note-uncertain", "1.1.0")]
    public void Cross_profile_catalog_identity_is_rejected(string id, string wrongCatalog)
    {
        var raw = Load(id).Response;
        raw["payload"]!["thesis"]!["catalogVersion"] = wrongCatalog;
        Assert.Throws<JsonException>(() => AnalysisJson.ParseResponse(raw.ToJsonString()));
    }

    [Theory]
    [InlineData("profile")][InlineData("root")][InlineData("workType")][InlineData("source")]
    public void Exact_unicode_key_events_refuse_changed_capture_authority(string change)
    {
        var fixture = Load("literal-unicode-bom-crlf");
        var snapshot = fixture.Snapshot();
        var result = Assert.IsType<AnalysisResponse.Completed>(AnalysisJson.ParseResponse(fixture.Reply(snapshot, "r"))).Result;
        foreach (var item in result.Thesis!.Events.Where(e => e.Kind == "cite"))
        {
            var file = snapshot.Files.Single(f => f.FileId.ToString() == item.FileId);
            Assert.Equal(item.Text, Encoding.UTF8.GetString(file.Bytes.AsSpan()
                .Slice((int)item.Span.StartByte, (int)(item.Span.EndByte - item.Span.StartByte))));
        }
        snapshot = change switch {
            "profile" => snapshot with { Profile = new(AnalysisCatalog.KnuId, AnalysisCatalog.ThesisVersion) },
            "root" => snapshot with { ReferenceConfiguration = new("uncaptured") },
            "workType" => snapshot with { Configuration = new(AnalysisWorkType.Coursework) },
            _ => snapshot with { Files = snapshot.Files.SetItem(0, snapshot.Files[0] with { HasBom = false }) },
        };
        Assert.Throws<JsonException>(() => ThesisValidation.ValidateCapturedResult(result, snapshot));
    }

    [Theory]
    [InlineData("literal-postnote", "1.6.0", true)]
    [InlineData("legacy-note-uncertain", "1.5.0", false)]
    public async Task Report_displays_its_own_versioned_catalog(string id, string version, bool literalNotes)
    {
        var fixture = Load(id); var snapshot = fixture.Snapshot();
        var result = Assert.IsType<AnalysisResponse.Completed>(AnalysisJson.ParseResponse(fixture.Reply(snapshot, "r"))).Result;
        using var services = new ServiceCollection().AddLogging().BuildServiceProvider();
        await using var renderer = new HtmlRenderer(services, services.GetRequiredService<ILoggerFactory>());
        var html = await renderer.Dispatcher.InvokeAsync(async () =>
            (await renderer.RenderComponentAsync<ThesisReportView>(ParameterView.FromDictionary(new Dictionary<string, object?> {
                [nameof(ThesisReportView.Report)] = new AnalysisReport(snapshot, result, "r", 7),
                [nameof(ThesisReportView.IsCurrent)] = false,
            }))).ToHtmlString());
        Assert.Equal(version, result.Profile.Version);
        Assert.Contains("<h3>Cited thesis source observations</h3>", html);
        Assert.DoesNotContain("opt-in " + version, html);
        Assert.Equal(literalNotes, html.Contains("Profile 1.6:", StringComparison.Ordinal));
        Assert.Contains("Incomplete standards coverage", html);
        Assert.DoesNotContain("data-testid=\"preview-fix\"", html);
    }
}
